const raw = $input.first().json;
const d = raw.output || raw;
const notion = $('Code - Extraer Datos').first().json;
const empresa = d.empresa || 'Cliente';
const fecha = new Date().toLocaleDateString('es-AR');

// ---------------------------------------------------------------------
// ERP -- primero el CRM, despues la transcripcion.
//
// El orden importa: 'property_que_sistema_usan' lo carga una persona a
// mano; 'erp_actual' lo interpreta el modelo desde el audio, y Fathom
// transcribe pesimo los nombres de ERP. En una discovery real "Finnegans"
// aparecio como Finance, Finex, Fan, Finegan y Fin -- cinco variantes en
// la misma llamada. Escribir cualquiera de esas en una propuesta es que
// el cliente lea su propio sistema mal escrito.
//
// Si no se sabe cual usa, el placeholder queda en la palabra generica
// 'ERP': la frase del slide sigue leyendose bien ("...con su ERP"),
// mientras que "No informado" ahi adentro queda roto. En la ficha de
// datos de mas abajo si se escribe 'No mencionado', porque es una lista
// de campos y no una oracion.
// ---------------------------------------------------------------------
const erpNotion = (notion.property_que_sistema_usan || '').toString().trim();
const erpIa = (d.erp_actual || '').toString().trim();
const erpReal = erpNotion || erpIa;
const erp = erpReal || 'ERP';

const puntos = Array.isArray(d.puntos_mejora) ? d.puntos_mejora.slice(0, 4) : [];
const beneficios = Array.isArray(d.beneficios) ? d.beneficios.slice(0, 4) : [];
const out = { empresa, fecha, erp };
for (let i = 0; i < 4; i++) {
  const p = puntos[i];
  out['punto' + (i + 1) + 'Titulo'] = p ? p.titulo : '';
  out['punto' + (i + 1) + 'Texto'] = p ? p.texto : '';
  const b = beneficios[i];
  out['ben' + (i + 1) + 'Nombre'] = b ? b.beneficio : '';
  out['ben' + (i + 1) + 'Actual'] = b ? b.situacion_actual : '';
  out['ben' + (i + 1) + 'Xtract'] = b ? b.con_xtract : '';
  out['ben' + (i + 1) + 'Mejora'] = b ? b.mejora : '';
}
out.fichaTexto = [
  'Empresa: ' + (d.empresa || 'No mencionado'),
  'Industria: ' + (d.industria || 'No mencionado'),
  'Tamano: ' + (d.tamano || 'No mencionado'),
  'Pais: ' + (d.pais || 'No mencionado'),
  'ERP actual: ' + (erpReal || 'No mencionado'),
  'Volumen de facturas mensual: ' + (d.volumen_facturas_mensual || 'No mencionado'),
  'Gasto anual en compras: ' + (d.gasto_anual_compras || 'No mencionado'),
  'Personas dedicadas a carga de facturas: ' + (d.personas_carga_facturas || 'No mencionado'),
  'Como gestionan hoy las facturas: ' + (d.gestion_actual_facturas || 'No mencionado'),
  'Problemas identificados: ' + (d.problemas_identificados || 'No mencionado'),
  'Fit con Xtract: ' + (d.fit_xtract || 'No mencionado'),
  'Nivel de interes: ' + (d.nivel_interes || 'No mencionado'),
  'Proximos pasos: ' + (d.proximos_pasos || 'No mencionado'),
  'Notas adicionales: ' + (d.notas_adicionales || 'No mencionado')
].join('\n');
out.puntosTexto = puntos.length ? puntos.map((p, i) => (i + 1) + '. ' + p.titulo + '\n' + p.texto).join('\n\n') : 'Sin puntos detectados';
out.beneficiosTexto = beneficios.length ? beneficios.map((b) => b.beneficio + ' | Antes: ' + b.situacion_actual + ' | Con Xtract: ' + b.con_xtract + ' | Mejora: ' + b.mejora).join('\n') : 'Sin beneficios detectados';
return [{ json: out }];

