parameters.jsCode:
const MAX = 120000;

// Entra el texto plano que devuelve "Drive - export texto" (HTTP Request con
// responseFormat text -> outputPropertyName 'data' por defecto).
const texto = String($input.first().json.data || '').trim().slice(0, MAX);

// SIN ESTA GUARDA EL FALLO ES SILENCIOSO, que es lo peor que puede pasar aca.
// Con la transcripcion vacia el extractor no encuentra nada, 'empresa' cae en
// el default 'Cliente', y el flujo IGUAL copia la plantilla y genera un Slide
// completo con los 25 placeholders en blanco, titulado
// "Propuesta - Cliente - <fecha>". No falla nada: queda una propuesta vacia
// esperando en Drive, y nadie se entera hasta que un comercial la abre
// delante del cliente.
//
// Causa mas probable: el endpoint /export de Drive solo exporta documentos
// NATIVOS de Google. Si el link de Notion apunta a un PDF o a un .docx
// subido, Drive contesta 403 fileNotExportable y aca llega vacio.
if (!texto) {
  throw new Error(
    'La transcripcion llego vacia, se corta antes de generar una propuesta en blanco. ' +
    'Revisa que el link de Notion apunte a un Google Doc nativo: ' +
    '/export no exporta PDFs ni archivos subidos.'
  );
}

return [{ json: { transcripcion: texto } }];

// El webhook suele envolver los datos en "body", por las dudas atajamos ambos casos
const data = $input.first().json.body || $input.first().json;

// Extraer link y owner del JSON de Notion
const link = data.property_link_a_discovery || "";
const owners = data.property_owner || [];
const ownerEmail = owners.length > 0 ? owners[0] : "";

// Extraer ID del documento usando Regex
let fileId = "";
const match = link.match(/\/d\/([a-zA-Z0-9-_]+)/);
if (match) {
  fileId = match[1];
}

// Extraer variables comerciales si ya vienen cargadas en Notion
const oneshot = parseFloat(data.property_one_shot) || 0;
const fee = parseFloat(data.property_mrr) || 0;
const facturasNotion = parseFloat(data.property_cantidad_de_facturas) || 0;

return [{
  json: {
    ...data,
    fileId: fileId,
    ownerEmail: ownerEmail,
    oneshot: oneshot,
    fee: fee,
    facturas_notion: facturasNotion
  }
}];

// =====================================================================
// CALCULO AUTOMATICO DE IMPACTO ECONOMICO Y ROI (PAGINA 4 Y GOOGLE DOC)
// =====================================================================
const RATES = { "Argentina": 10.10, "Uruguay": 9.30, "Ecuador": 5.45, "Costa Rica": 8.10, "Honduras": 5.80, "Panamá": 5.40, "México": 5.25, "Bolivia": 5.13, "Guatemala": 5.25, "Chile": 5.00, "Perú": 4.35, "Paraguay": 4.40, "Rep. Dominicana": 3.90, "Colombia": 3.60, "Brasil": 4.05, "El Salvador": 3.65, "Venezuela": 2.70 };
const PREFIJOS = [ ["549", "Argentina"], ["54", "Argentina"], ["598", "Uruguay"], ["56", "Chile"], ["57", "Colombia"], ["52", "México"], ["51", "Perú"], ["593", "Ecuador"], ["506", "Costa Rica"], ["507", "Panamá"], ["502", "Guatemala"], ["504", "Honduras"], ["503", "El Salvador"], ["591", "Bolivia"], ["595", "Paraguay"], ["1809", "Rep. Dominicana"], ["1829", "Rep. Dominicana"], ["1849", "Rep. Dominicana"], ["55", "Brasil"], ["58", "Venezuela"] ];

const FACTURAS_POR_PERSONA_MES = 300;
const USD_POR_FACTURA = 400;
const HS_ANIO_FULLTIME = 1200;
const HS_ANIO_PARTTIME = 600;
const PCT = { A: 1.0, B: 0.3, C: 1.0, D: 1.0, E: 1.5 };

const norm = (s) => (s || "").toString().normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().trim();
const fmtUSD = (n) => Math.round(n).toLocaleString("es-AR");
const fmtPct1 = (n) => n.toLocaleString("es-AR", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const fmt = (n) => "USD " + fmtUSD(n);

const notion = $("Code - Extraer Datos").first().json;
const iaRaw = $("IA - Extraer datos de la llamada").first().json;
const ia = iaRaw.output || iaRaw;
const presentationId = $("Copiar plantilla de propuesta").first().json.id;
const slideUrl = "https://docs.google.com/presentation/d/" + presentationId + "/edit";
const empresa = ia.empresa || notion.property_nombre_oportunidad || "Cliente";

// PAIS
const PAISES = Object.keys(RATES);
const matchPais = (v) => {
  const n = norm(v);
  if (!n) return "";
  return PAISES.find((p) => norm(p) === n) || PAISES.find((p) => n.indexOf(norm(p)) !== -1) || "";
};

const paisNotion = matchPais(Array.isArray(notion.property_pais) ? notion.property_pais[0] : notion.property_pais);
const paisIa = matchPais(ia.pais);
let paisTel = "";
let prefTel = "";
const telDigitos = String(notion.property_whatsapp_kdm || "").replace(/\D/g, "");
for (const [pref, p] of PREFIJOS) {
  if (telDigitos.indexOf(pref) === 0) { paisTel = p; prefTel = pref; break; }
}
const pais = paisNotion || paisIa || paisTel || "";
const paisOrigen = paisNotion ? "card de Notion" : (paisIa ? "la transcripcion" : (paisTel ? "el prefijo del telefono (+" + prefTel + ")" : ""));

// DEDICACION
const dedicRaw = norm(ia.dedicacion_personas);
const esPartTime = dedicRaw.indexOf("part") !== -1;
const dedicacionConocida = esPartTime || dedicRaw.indexOf("full") !== -1;
const dedicacion = esPartTime ? "part-time" : "full-time";
const hsPorPersona = esPartTime ? HS_ANIO_PARTTIME : HS_ANIO_FULLTIME;

// FACTURAS
const aFacturasMes = (v) => {
  if (v == null || v === "") return null;
  if (typeof v === "number") return v > 0 ? v : null;
  const s = String(v);
  const nums = (s.replace(/[.,](?=\d{3}\b)/g, "").match(/\d+/g) || []).map(Number).filter((n) => n > 0);
  if (!nums.length) return null;
  let n = Math.max.apply(null, nums);
  if (/anual|al año|por año|\/año|anuales/i.test(s)) n = n / 12;
  return n > 0 ? n : null;
};

const factNotion = aFacturasMes(notion.property_cantidad_de_facturas || notion.facturas_notion);
const factIa = aFacturasMes(ia.volumen_facturas_mensual);
const facturasMes = factNotion || factIa;
const facturasOrigen = factNotion ? "card de Notion" : (factIa ? "la transcripcion" : "");

const personas = facturasMes ? Math.max(1, Math.ceil(facturasMes / FACTURAS_POR_PERSONA_MES)) : null;
const gasto = facturasMes ? facturasMes * 12 * USD_POR_FACTURA : null;

const faltan = [];
if (!facturasMes) faltan.push("la cantidad de facturas");
if (!pais) faltan.push("el pais");

if (faltan.length) {
  return [{ json: {
    calculable: false,
    tiene_precio: false,
    presentationId: presentationId,
    slideUrl: slideUrl,
    empresa: empresa,
    pais: pais,
    paisOrigen: paisOrigen,
    gastoPrefill: gasto ? String(Math.round(gasto)) : "",
    personasPrefill: personas ? String(personas) : "",
    dedicacion: dedicacion,
    dedicacionConocida: dedicacionConocida,
    facturasMes: facturasMes ? Math.round(facturasMes) : null,
    facturasOrigen: facturasOrigen,
    motivo: "Falta " + faltan.join(" y ") + "."
  } }];
}

// PERDIDAS Y CALCULOS
const hora = RATES[pais] || 8.74;
const valA = gasto * PCT.A / 100;
const valB = gasto * PCT.B / 100;
const valC = gasto * PCT.C / 100;
const valD = gasto * PCT.D / 100;
const valE = gasto * PCT.E / 100;
const subtotal = valA + valB + valC + valD + valE;
const hsAnio = personas * hsPorPersona;
const rrhh = Math.round(hsAnio * hora);
const total = subtotal + rrhh;
const mensual = total / 12;

const oneshot = parseFloat(notion.oneshot || notion.property_one_shot) || 0;
const fee = parseFloat(notion.fee || notion.property_mrr) || 0;
const tienePrecio = (oneshot > 0 || fee > 0);

const s = personas !== 1 ? "s" : "";
const feeAnual = fee * 12;
const costo1 = oneshot + feeAnual;
const costo2 = feeAnual;
const roi1 = costo1 > 0 ? ((total - costo1) / costo1 * 100) : 0;
const roi2 = costo2 > 0 ? ((total - costo2) / costo2 * 100) : 0;

return [{ json: {
  calculable: true,
  tiene_precio: tienePrecio,
  presentationId: presentationId,
  slideUrl: slideUrl,
  empresa: empresa,
  docName: "ROI Xtract - " + empresa,
  owner_slack: String(notion.ownerEmail || notion.owner_slack || "").trim(),
  facturasMes: Math.round(facturasMes),
  facturasOrigen: facturasOrigen,
  paisOrigen: paisOrigen,
  dedicacion: dedicacion,
  dedicacionConocida: dedicacionConocida,
  hsPorPersona: hsPorPersona,

  // Pagina 4 Slides
  gastoFmt: Math.round(gasto).toLocaleString("es-AR"),
  pais: pais,
  personas: String(personas),
  perdErrores: fmt(valA),
  perdFiscal: fmt(valB),
  perdDesc: fmt(valC),
  perdSobre: fmt(valD),
  perdDupes: fmt(valE),
  perdRrhh: fmt(rrhh),
  perdTotal: fmt(total),
  impactoTotal: fmtUSD(total),
  impactoMensual: fmtUSD(mensual),
  rrhhDetalle: personas + " persona" + s + " " + dedicacion + " × " + hsPorPersona.toLocaleString("es-AR") + " hs/año × USD " + hora.toFixed(2) + "/h (incluye leyes sociales)",

  // Documento ROI Google Docs
  docFacturasMencion: facturasMes > 0 ? fmtUSD(facturasMes) + " facturas mensuales" : "un volumen relevante de facturas",
  docBaseLaboral: personas + " analista" + s + " asignado" + s + " al proceso de AP en " + pais,
  docRrhhBase: personas + " persona" + s + " × " + hsPorPersona.toLocaleString("es-AR") + " hs/año × USD " + hora.toFixed(2) + "/h en " + pais + ", incl. cargas sociales",
  docVolumen: fmtUSD(gasto),
  docPctA: fmtPct1(PCT.A),
  docPctB: fmtPct1(PCT.B),
  docPctC: fmtPct1(PCT.C),
  docPctD: fmtPct1(PCT.D),
  docPctE: fmtPct1(PCT.E),
  docValA: fmtUSD(valA),
  docValB: fmtUSD(valB),
  docValC: fmtUSD(valC),
  docValD: fmtUSD(valD),
  docValE: fmtUSD(valE),
  docSubtotalAE: fmtUSD(subtotal),
  docValRrhh: fmtUSD(rrhh),
  docRecupero: fmtUSD(total),
  docOneshot: fmtUSD(oneshot),
  docFeeAnual: fmtUSD(feeAnual),
  docCosto1: fmtUSD(costo1),
  docCosto2: fmtUSD(costo2),
  docRoi1: Math.round(roi1) + "%",
  docRoi2: Math.round(roi2) + "%"
} }];

// =====================================================================
// ⚠️  MODO PRUEBA -- VACIAR ESTA CONSTANTE PARA VOLVER A LO NORMAL
//
// Mientras tenga un id adentro, TODOS los avisos van a esa persona sin
// importar de quien sea el lead. Con '' vuelve a mandarle al owner de la
// card, que es el comportamiento real.
//
//   U09FZ5MLF0E = Ian Brandan
// =====================================================================
const FORZAR_DESTINATARIO = 'D0BRPUE84UA';
const extraerNode = $('Code - Extraer Datos').first().json || {};
const rawId = (extraerNode.id || extraerNode.page_id || '').replace(/-/g, '');
const notionUrl = extraerNode.url || (rawId ? ('https://www.notion.so/' + rawId) : '');

// =====================================================================
// DM por Slack al owner de la card avisandole que la propuesta ya esta.
//
// POR QUE HAY QUE RESOLVER EL ID A MANO:
// Notion nos da el MAIL del owner ('nicolas.gonzalez@xtract.app'), pero
// Slack solo notifica con su member id ('U02MCAHHM1T'). El endpoint que
// traduce mail -> id (users.lookupByEmail) necesita el scope
// 'users:read.email', que la app "Xtract notifications" NO tiene: por eso
// ningun perfil de users.list trae 'email'. Se cruza por el handle, que
// en este workspace coincide con la parte del mail antes del @.
// =====================================================================

// =====================================================================
// LOS DOS FORMULARIOS
//
// Hay dos entradas distintas al mismo calculo, y cual se ofrece depende
// de si la pagina 4 se pudo escribir sola:
//
//   SOLO EL PRECIO -- la pagina 4 ya esta escrita, o sea que todos los
//   datos del cliente ya se conocen. Viajan ocultos en el link y el
//   comercial carga unicamente one-shot y fee. No es solo comodidad: si
//   se los volvieramos a pedir, podria tipear un gasto distinto al que
//   ya quedo impreso en el slide, y el documento ROI terminaria
//   contradiciendo a la propuesta que lo acompania.
//
//   COMPLETO -- falto algun dato, o el comercial quiere corregir alguno.
//   Se piden todos.
//
// ⚠️ AL IMPORTAR ESTE WORKFLOW A PRODUCCION las dos constantes tienen que
// pasar a la forma con ruta fija ('/form/pagina-4-impacto' y
// '/form/roi-precio'), porque n8n REGENERA el webhookId al importar.
// Ver el cartel rojo del canvas. Ya paso una vez: los links quedaron 404.
//
// El prefill por query param SOLO funciona en la URL de PRODUCCION del
// formulario: en modo test n8n ignora los parametros y sale vacio.
// =====================================================================
const FORM_COMPLETO = 'https://n8n.xtract.app/form/67a71cbf-61e2-4ea2-84eb-da9f19dde455';
const FORM_SOLO_PRECIO = 'https://n8n.xtract.app/form/roi-precio';

const c = $('Calcular impacto economico').first().json;
const notion = $('Code - Extraer Datos').first().json;

const norm = (s) => String(s == null ? '' : s)
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().trim();

const ownerEmail = (Array.isArray(notion.property_owner) ? notion.property_owner[0] : notion.property_owner) || '';
const local = norm(ownerEmail.split('@')[0]);

const usuarios = $input.all().map((i) => i.json)
  .filter((u) => u && u.id && !u.deleted && !u.is_bot);

let owner = null;
if (local) {
  // 1) handle exacto: 'nicolas.gonzalez'
  owner = usuarios.find((u) => norm(u.name) === local) || null;
  // 2) nombre real: 'nicolas.gonzalez' -> 'nicolas gonzalez'
  if (!owner) {
    const comoNombre = local.replace(/[._-]+/g, ' ');
    owner = usuarios.find((u) => norm(u.real_name) === comoNombre) || null;
  }
}

// Query string compartido por los dos formularios. Los nombres tienen que
// coincidir con los fieldName de cada Form Trigger -- en el corto, los
// mismos campos existen pero como hiddenField.
//
// El precio (oneshot/fee) NO se precarga a proposito: es el unico dato
// que la automatizacion no puede saber, y precargarlo con un valor
// "tipico" es exactamente como termina saliendo una propuesta con el fee
// de otro deal.
//
// El desplegable de dedicacion espera la etiqueta con mayuscula
// ('Full-time' / 'Part-time'), no el valor interno en minuscula.
const dedicLabel = c.dedicacion === 'part-time' ? 'Part-time' : 'Full-time';
const qs = [];
qs.push('presentacion=' + encodeURIComponent(c.slideUrl || ''));
if (c.empresa) qs.push('empresa=' + encodeURIComponent(c.empresa));
if (c.pais) qs.push('pais=' + encodeURIComponent(c.pais));
if (c.gastoPrefill) qs.push('gasto=' + encodeURIComponent(c.gastoPrefill));
else if (c.calculable && c.gastoFmt) qs.push('gasto=' + encodeURIComponent(String(c.gastoFmt).replace(/\./g, '')));
if (c.personasPrefill) qs.push('personas=' + encodeURIComponent(c.personasPrefill));
else if (c.calculable && c.personas) qs.push('personas=' + encodeURIComponent(c.personas));
if (c.facturasMes) qs.push('facturas=' + encodeURIComponent(c.facturasMes));
qs.push('dedicacion=' + encodeURIComponent(dedicLabel));

// El formulario no tiene forma de saber a quien avisarle: lo abre
// cualquiera que tenga el link, y no hay login. Por eso el destinatario
// viaja EN el link, en un campo oculto ('owner_slack'), y vuelve con el
// envio. Asi el aviso de "ya estan los dos documentos" le llega a la
// misma persona que recibio este DM.
//
// Va el mismo id que usa este mensaje, asi que en modo prueba el aviso
// del formulario tambien queda desviado y no se le escapa a un owner real.
const destinatario = FORZAR_DESTINATARIO || (owner ? owner.id : '');
if (destinatario) qs.push('owner_slack=' + encodeURIComponent(destinatario));

const query = '?' + qs.join('&');
const urlCompleto = FORM_COMPLETO + query;
const urlSoloPrecio = FORM_SOLO_PRECIO + query;

let bloque;
if (c.calculable) {
  bloque = [
    '*Impacto economico (pagina 4)* — ya escrito en el slide',
    '• Facturas: ' + c.facturasMes + '/mes  →  gasto anual estimado USD ' + c.gastoFmt,
    '• Pais: ' + c.pais + '  •  Personas en el proceso: ' + c.personas + ' (' + c.dedicacion + ', ' + c.hsPorPersona + ' hs/año c/u)',
    '• Perdida anual estimada: ' + c.perdTotal + '  (USD ' + c.impactoMensual + '/mes)'
  ];
  // Solo se avisa de lo que NO se pudo confirmar contra el CRM. La
  // dedicacion no entra aca: full-time es la regla, no una suposicion, y
  // una alerta que salta en todas las propuestas es una alerta que nadie
  // lee. El dato igual esta arriba, en el cuerpo del mensaje.
  const alertas = [];
  if (c.facturasOrigen !== 'card de Notion') {
    alertas.push(':warning: Las facturas (' + c.facturasMes + '/mes) salieron de ' + c.facturasOrigen + ', no del CRM. Verificalas.');
  }
  if (c.paisOrigen !== 'card de Notion') {
    alertas.push(':warning: El pais (' + c.pais + ') se dedujo de ' + c.paisOrigen + '. Verificalo.');
  }
  if (alertas.length) {
    bloque = bloque.concat(['']).concat(alertas)
      .concat(['_Si un numero esta mal, hay que volver a generar la propuesta: la pagina 4 ya quedo escrita y no se puede reescribir desde el formulario._']);
  }
} else {
  // Falta algo: el slide quedo INTACTO a proposito, con los placeholders
  // en su lugar, que es lo unico que le permite al formulario escribirlos.
  bloque = [
    ':pushpin: *La pagina 4 quedo pendiente.* ' + (c.motivo || ''),
    'El slide esta sin tocar a proposito: los marcadores siguen ahi, asi el formulario los puede completar.'
  ];
  const yaCargado = [];
  if (c.gastoPrefill) yaCargado.push('gasto USD ' + Number(c.gastoPrefill).toLocaleString('es-AR'));
  if (c.personasPrefill) yaCargado.push(c.personasPrefill + ' persona(s) ' + c.dedicacion);
  if (c.pais) yaCargado.push('pais ' + c.pais);
  bloque.push(yaCargado.length
    ? '_Ya va precargado: el link del Slides, ' + yaCargado.join(', ') + '. Solo falta lo demas._'
    : '_Va precargado el link del Slides. El resto hay que completarlo._');
  // Aca SI se menciona: la persona esta por completar el formulario y
  // todavia puede cambiarlo. Se avisa donde se puede actuar.
  if (!c.dedicacionConocida) {
    bloque.push('_La llamada no aclaro la dedicacion, asi que el formulario viene en Full-time. Cambialo si corresponde._');
  }
}

// ---------------------------------------------------------------------
// DOCUMENTO ROI
//
// El link va SIEMPRE, en las dos ramas: el documento no depende de que la
// pagina 4 se haya podido calcular, depende del PRECIO. Lo que cambia es
// A CUAL de los dos formularios se manda.
// ---------------------------------------------------------------------
let bloqueRoi;
if (c.calculable) {
  // Todo conocido: formulario corto. El comercial ve dos campos, no diez.
  bloqueRoi = [
    '',
    ':bar_chart: *Documento ROI* — todavia no esta generado.',
    'Falta solo el precio cotizado. Los datos de arriba ya van cargados.',
    '',
    ':pencil: <' + urlSoloPrecio + '|Cargar el precio y generar el ROI>',
    '_Son dos campos: implementacion y fee mensual._',
    '_Si alguno de los datos de arriba esta mal, <' + urlCompleto + '|usa el formulario completo> — ojo que la pagina 4 del slide ya quedo escrita y no se reescribe._'
  ];
} else {
  bloqueRoi = [
    '',
    ':bar_chart: *Documento ROI* — todavia no esta generado.',
    'Necesita el precio cotizado (implementacion y fee mensual), que la automatizacion no puede saber.',
    '',
    ':pencil: <' + urlCompleto + '|Completar la pagina 4 y generar el ROI>',
    '_El mismo envio hace las dos cosas._'
  ];
}
bloqueRoi.push('_Cuando esten los dos, te llega otro aviso por aca._');

// Si el DM esta desviado por la constante de prueba, que se note en el
// propio mensaje. Un aviso de prueba que se lee igual que uno real es la
// forma mas facil de que alguien actue sobre el lead equivocado.
const notaPrueba = [];

const texto = [
  ':page_facing_up: *Propuesta generada* — ' + c.empresa,
  '<' + c.slideUrl + '|Abrir la propuesta en Slides>' + (notionUrl ? ' • <' + notionUrl + '|Abrir card en Notion>' : ''),
  ''
].concat(bloque)
 .concat(bloqueRoi)
 .concat(notaPrueba.length ? [''].concat(notaPrueba) : [])
 .concat(['', '_Revisala antes de mandarla: los textos los redacto un modelo._'])
 .join('\n');

return [{ json: {
  texto_slack: texto,
  owner_email: ownerEmail,
  form_url: c.calculable ? urlSoloPrecio : urlCompleto,
  pagina4_completada: !!c.calculable,
  // A quien le hubiera llegado de verdad, para poder auditarlo aunque el
  // envio este desviado por la constante de prueba.
  owner_slack_id_real: owner ? owner.id : '',
  owner_encontrado: !!owner,
  owner_slack_id: FORZAR_DESTINATARIO || (owner ? owner.id : '')
} }];

// =====================================================================
// Completa la pagina 4 del slide Y arma el documento ROI de Google Docs.
//
// Las dos salidas se calculan en UNA sola pasada. Si alguien duplicara la
// cuenta para el documento, la misma propuesta podria mostrar un total en
// el slide y otro distinto en el Word, delante del cliente.
//
// OJO: la formula esta espejada en 'Calcular impacto economico', el nodo
// de la cadena automatica de este mismo workflow. Si cambia un
// porcentaje, cambian los dos. Unificarlos en un solo nodo es el
// siguiente paso pendiente.
// =====================================================================

// LO ALIMENTAN DOS FORMULARIOS y por eso este nodo es el unico que los
// conoce a los dos:
//   - 'Formulario - solo el precio': la pagina 4 ya se escribio sola, asi
//     que el comercial solo carga one-shot y fee; el resto viaja oculto.
//   - 'Formulario - pagina 4 y ROI': falto algun dato, se piden todos.
// Todo lo que necesiten los nodos de abajo sale de ACA, nunca de
// $('<nombre del trigger>'): referenciar un trigger que no corrio hace
// fallar la ejecucion entera.
const d = $input.first().json;

const RATES = { 'Argentina': 10.10, 'Uruguay': 9.30, 'Ecuador': 5.45, 'Costa Rica': 8.10, 'Honduras': 5.80, 'Panamá': 5.40, 'México': 5.25, 'Bolivia': 5.13, 'Guatemala': 5.25, 'Chile': 5.00, 'Perú': 4.35, 'Paraguay': 4.40, 'Rep. Dominicana': 3.90, 'Colombia': 3.60, 'Brasil': 4.05, 'El Salvador': 3.65, 'Venezuela': 2.70 };

// Un solo lugar para los porcentajes de perdida.
//
// Antes el multiplicador (0.015) y el rotulo impreso (1,5%) eran dos
// literales separados, y ya se desincronizaron una vez: la tabla decia
// 1,5% mientras la cuenta hacia 0,1%. Ahora el documento IMPRIME este
// numero y MULTIPLICA por este mismo numero, asi que no pueden diferir.
// Definido por el cliente: pagos duplicados = 1,5%.
const PCT = { A: 1.0, B: 0.3, C: 1.0, D: 1.0, E: 1.5 };

const fmtUSD = (n) => Math.round(n).toLocaleString('es-AR');
const fmtPct1 = (n) => n.toLocaleString('es-AR', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const fmt = (n) => 'USD ' + fmtUSD(n);

let pres = String(d.presentacion || '').trim();
const m = pres.match(/\/d\/([a-zA-Z0-9_-]+)/);
const presentationId = m ? m[1] : pres;

const empresa = String(d.empresa || '').trim() || 'la empresa';
const gasto = parseFloat(d.gasto) || 0;
const personas = parseFloat(d.personas) || 0;
const facturas = parseFloat(d.facturas) || 0;
const pais = d.pais || 'Uruguay';
const hora = RATES[pais] || 8.74;
const oneshot = parseFloat(d.oneshot) || 0;
const fee = parseFloat(d.fee) || 0;

// Sin precio no hay ROI. Con costo cero la formula daria 0% de retorno y
// el documento saldria igual, con un numero sin sentido y la firma de
// Xtract abajo. Es preferible que corte aca.
if (oneshot <= 0 && fee <= 0) {
  throw new Error('Falta el precio cotizado: carga el one-shot o el fee mensual. Sin eso el ROI del documento no significa nada.');
}

// Dedicacion: full-time 1.200 hs/anio por persona, part-time 600. Si el
// campo llegara vacio cae en full-time, que es como venia calculando esto
// desde siempre -- asumir part-time bajaria el impacto de todas las
// propuestas sin que nadie lo haya pedido.
const esPartTime = /part/i.test(String(d.dedicacion || ''));
const hsPorPersona = esPartTime ? 600 : 1200;
const dedicacion = esPartTime ? 'part-time' : 'full-time';

const valA = gasto * PCT.A / 100;
const valB = gasto * PCT.B / 100;
const valC = gasto * PCT.C / 100;
const valD = gasto * PCT.D / 100;
const valE = gasto * PCT.E / 100;
const subtotal = valA + valB + valC + valD + valE;

const hsAnio = personas * hsPorPersona;
const rrhh = Math.round(hsAnio * hora);
const total = subtotal + rrhh;
const mensual = total / 12;

const feeAnual = fee * 12;
const costo1 = oneshot + feeAnual;
const costo2 = feeAnual;
const roi1 = costo1 > 0 ? ((total - costo1) / costo1 * 100) : 0;
const roi2 = costo2 > 0 ? ((total - costo2) / costo2 * 100) : 0;

// Los plurales se resuelven ACA, no en la plantilla: Google Docs
// reemplaza texto pero no tiene condicionales, asi que un {{PERSONAS}}
// suelto terminaria escribiendo "1 personas asignados al proceso".
const s = personas !== 1 ? 's' : '';

return [{ json: {
  presentationId,
  empresa,
  docName: 'ROI Xtract - ' + empresa,

  // Viaja oculto desde el link del DM. Se normaliza aca para que el aviso
  // final no tenga que saber cual de los dos formularios disparo.
  owner_slack: String(d.owner_slack || '').trim(),

  // ---- Pagina 4 del slide (13 marcadores) ----
  gastoFmt: gasto.toLocaleString('es-AR'),
  pais,
  personas: String(personas),
  dedicacion,
  perdErrores: fmt(valA),
  perdFiscal: fmt(valB),
  perdDesc: fmt(valC),
  perdSobre: fmt(valD),
  perdDupes: fmt(valE),
  perdRrhh: fmt(rrhh),
  perdTotal: fmt(total),
  impactoTotal: fmtUSD(total),
  impactoMensual: fmtUSD(mensual),
  rrhhDetalle: personas + ' persona' + s + ' ' + dedicacion + ' × ' + hsPorPersona.toLocaleString('es-AR') + ' hs/año × USD ' + hora.toFixed(2) + '/h (incluye leyes sociales)',

  // ---- Documento ROI en Docs (24 marcadores) ----
  // Van SIN el prefijo 'USD': esa palabra ya esta escrita en la plantilla.
  docFacturasMencion: facturas > 0 ? fmtUSD(facturas) + ' facturas mensuales' : 'un volumen relevante de facturas',
  docBaseLaboral: personas + ' analista' + s + ' asignado' + s + ' al proceso de AP en ' + pais,
  docRrhhBase: personas + ' persona' + s + ' × ' + hsPorPersona.toLocaleString('es-AR') + ' hs/año × USD ' + hora.toFixed(2) + '/h en ' + pais + ', incl. cargas sociales',
  docVolumen: fmtUSD(gasto),
  docPctA: fmtPct1(PCT.A),
  docPctB: fmtPct1(PCT.B),
  docPctC: fmtPct1(PCT.C),
  docPctD: fmtPct1(PCT.D),
  docPctE: fmtPct1(PCT.E),
  docValA: fmtUSD(valA),
  docValB: fmtUSD(valB),
  docValC: fmtUSD(valC),
  docValD: fmtUSD(valD),
  docValE: fmtUSD(valE),
  docSubtotalAE: fmtUSD(subtotal),
  docValRrhh: fmtUSD(rrhh),
  docRecupero: fmtUSD(total),
  docOneshot: fmtUSD(oneshot),
  docFeeAnual: fmtUSD(feeAnual),
  docCosto1: fmtUSD(costo1),
  docCosto2: fmtUSD(costo2),
  docRoi1: Math.round(roi1) + '%',
  docRoi2: Math.round(roi2) + '%'
} }];

const FORZAR_DESTINATARIO = 'D0BRPUE84UA';

const isOneShot = $('Calcular impacto economico').isExecuted && $('Tiene precio?').first().json.tiene_precio;
const c = isOneShot ? $('Calcular impacto economico').first().json : $('Calcular impacto y ROI (formulario)').first().json;
const docNode = isOneShot ? $('Copiar plantilla del ROI (OneShot)') : $('Copiar plantilla del ROI');
const docId = docNode.first().json.id;

const slideUrl = 'https://docs.google.com/presentation/d/' + c.presentationId + '/edit';
const docUrl = 'https://docs.google.com/document/d/' + docId + '/edit';

// Extraer link de la card de Notion (robusto: usa url original o construye link directo con el ID limpio)
const extraerNode = $('Code - Extraer Datos').first().json || {};
const rawId = (extraerNode.id || extraerNode.page_id || '').replace(/-/g, '');
const notionUrl = extraerNode.url || (rawId ? ('https://www.notion.so/' + rawId) : '');

const destinatario = FORZAR_DESTINATARIO || String(c.owner_slack || '').trim();

const links = [
  ':bar_chart: <' + docUrl + '|Abrir el documento ROI>',
  ':page_facing_up: <' + slideUrl + '|Abrir la propuesta en Slides>'
];
if (notionUrl) {
  links.push(':link: <' + notionUrl + '|Abrir card en Notion>');
}

const texto = [
  ':white_check_mark: *Los dos documentos ya estan generados* — ' + c.empresa,
  '',
  ...links,
  '',
  '• Gasto anual en proveedores: USD ' + c.docVolumen,
  '• Recupero potencial: USD ' + c.docRecupero + ' / año',
  '• Costo Xtract año 1: USD ' + c.docCosto1 + '  →  ROI ' + c.docRoi1,
  '• Año 2 en adelante: USD ' + c.docCosto2 + '  →  ROI ' + c.docRoi2,
  '',
  '_' + c.docBaseLaboral + '._',
  '',
  '_Revisa los dos antes de mandarlos: los textos los redacto un modelo._'
].join('\n');

return [{ json: {
  texto_slack: texto,
  owner_slack_id: destinatario,
  hay_destinatario: !!destinatario,
  doc_url: docUrl,
  slide_url: slideUrl,
  notion_url: notionUrl
} }];

